import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { CompanyService } from 'src/app/service/company/company.service';
import { AuthStateService } from 'src/app/shared/services/auth-state.service';

@Component({
  selector: 'app-company',
  templateUrl: './company.component.html',
  styleUrls: ['./company.component.css']
})
export class CompanyComponent implements OnInit {
  companyId!: number;
  company!: Company;
  jobs: Job[] = [];

  isLoggedIn = false;
  initials = '';
  profileRoute = '/';

  constructor(
    private readonly compService: CompanyService,
    private readonly route: ActivatedRoute,
    private readonly authState: AuthStateService
  ) {}

  ngOnInit(): void {
    const routeId = this.route.snapshot.paramMap.get('id');
    if (routeId) {
      this.companyId = Number(routeId);
    } else {
      const id = this.authState.id;
      this.companyId = id ?? 0;
    }

    this.isLoggedIn = this.authState.isLoggedIn;
    this.profileRoute = this.authState.profileRoute;

    if (this.isLoggedIn && this.authState.id !== null) {
      const id = this.authState.id;
      if (this.authState.role === 'COMPANY') {
        this.compService.getCompanyById(id).subscribe((company: Company) => {
          this.initials = this.authState.initialsFromCompany(company);
        });
      } else {
        // seeker case: still pass empty initials — minimal data
        this.initials = '';
      }
    }

    if (this.companyId > 0) {
      this.compService.getCompanyById(this.companyId).subscribe((res: Company) => (this.company = res));
      this.compService.getJobsByCompany(this.companyId).subscribe((res: Job[]) => (this.jobs = res));
    }
  }

  logout(): void {
    this.authState.logout();
  }
}
